from openpyxl import load_workbook
from math import hypot
f='/filesystem/Birchwood/PackageA/05_Field/Settlement_Monitoring_BlockC.xlsx'
w=load_workbook(f,data_only=True); s=w['Readings']
# map ids MP1..12 from grid listed in monitor points; cols A-D coords 0-3; rows 1-3 coords 0-2
coords={1:(0,0),2:(1,0),3:(2,0),4:(3,0),5:(0,1),6:(1,1),7:(2,1),8:(3,1),9:(0,2),10:(1,2),11:(2,2),12:(3,2)}
vals={i:s.cell(19,3+i).value for i in range(1,13)}
print('latest values',vals)
for limit in [30,35.5,1000]:
 pairs=[]
 for i in vals:
  for j in vals:
   if j<=i: continue
   d=hypot((coords[i][0]-coords[j][0])*24,(coords[i][1]-coords[j][1])*26)
   if d<=limit:
    pairs.append((abs(vals[i]-vals[j]),d,i,j,vals[i],vals[j]))
 print('limit',limit,'max',max(pairs))
 print('top five',sorted(pairs,reverse=True)[:5])
